package com.example.todolist;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import java.util.*;
/** Text-only report; the values stay strings so existing Firestore rules and reports remain compatible. */
public class ReportFragment extends Fragment{
 private TextView status;private Spinner site,block;private EditText floor,location;private LinearLayout materials;private Button submit;
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_report,p,false);status=v.findViewById(R.id.tvReportStatus);site=v.findViewById(R.id.spSite);block=v.findViewById(R.id.spBlock);floor=v.findViewById(R.id.etFloor);location=v.findViewById(R.id.etLocation);materials=v.findViewById(R.id.chipMaterials);submit=v.findViewById(R.id.btnSubmitReport); set(site,new String[]{"Selecciona la sede *","Sede 1","Sede 2","Sede 3","Sede 4","Sede 5","Sede 6"});set(block,new String[]{"Selecciona el bloque *","Bloque A","Bloque B","Bloque C","Bloque D","Bloque E","Bloque F","Bloque G","Bloque H","Bloque I","Bloque J","Bloque K","Sin bloque / zona exterior"});status.setText("Los reportes se revisan antes de publicarse. No necesitas fotografías.");submit.setOnClickListener(x->send());return v;}
 private void set(Spinner s,String[] values){s.setAdapter(new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_dropdown_item,values));}
 private void send(){com.google.firebase.auth.FirebaseUser cu=FirebaseGateway.auth().getCurrentUser();if(cu==null||!cu.isEmailVerified()){((MainActivity)requireActivity()).requireAccount("report");return;}String s=site.getSelectedItem().toString(),b=block.getSelectedItem().toString(),l=location.getText().toString().trim();List<String> chosen=new ArrayList<>();int[] options={R.id.chipPlastic,R.id.chipCaps,R.id.chipPaper,R.id.chipCardboard,R.id.chipGlass,R.id.chipElectronics,R.id.chipBulbs,R.id.chipOther};for(int id:options){CheckBox box=materials.findViewById(id);if(box!=null&&box.isChecked())chosen.add(box.getText().toString());}if(site.getSelectedItemPosition()==0||block.getSelectedItemPosition()==0||l.isEmpty()||chosen.isEmpty()){status.setText("Selecciona sede, bloque, residuos y escribe la ubicación exacta.");return;}submit.setEnabled(false);Map<String,Object> report=new HashMap<>();report.put("site",s);report.put("block",b);report.put("floor",floor.getText().toString().trim());report.put("location",l);report.put("materialsAccepted",android.text.TextUtils.join(", ",chosen));report.put("description","");report.put("coordinates",null);status.setText("Enviando reporte…");FirebaseGateway.submitReport(report,error->{submit.setEnabled(true);status.setText(error==null?"Reporte enviado como pendiente de aprobación.":"No fue posible enviar el reporte.");});}
}
